package com.tdeffectshider;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class TdEffectsHiderTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(TdEffectsHiderPlugin.class);
		RuneLite.main(args);
	}
}

package com.tdeffectshider;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("tdeffectshider")
public interface TdEffectsHiderConfig extends Config
{
	@ConfigItem(
		keyName = "hideBodyFire",
		name = "Body fire (shield)",
		description = "Hide the swirling fire shield spotanim on Tormented Demons (the main eye-strain).",
		position = 1
	)
	default boolean hideBodyFire()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideShieldRestore",
		name = "Shield re-activation",
		description = "Hide the fire flash when the demon restores its shield after a prayer/style swap.",
		position = 2
	)
	default boolean hideShieldRestore()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideMelee",
		name = "Melee swipe",
		description = "Hide the trail from the demon's melee attack.",
		position = 3
	)
	default boolean hideMelee()
	{
		return false;
	}

	@ConfigItem(
		keyName = "hideDeath",
		name = "Death burn",
		description = "Hide the fire spotanim when the demon dies.",
		position = 4
	)
	default boolean hideDeath()
	{
		return false;
	}

	@ConfigItem(
		keyName = "hideExplosion",
		name = "Fireball flash",
		description = "Hide the fire flash on the demon itself when it casts its fireball special (the flying fireballs stay visible).",
		position = 5
	)
	default boolean hideExplosion()
	{
		return false;
	}

	@ConfigItem(
		keyName = "hideSummon",
		name = "Spawn effect",
		description = "Hide the fire spotanim when the demon spawns in (e.g. after a kill).",
		position = 6
	)
	default boolean hideSummon()
	{
		return false;
	}
}

package com.tdeffectshider;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.ActorSpotAnim;
import net.runelite.api.NPC;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(
	name = "Tormented Demon Effects Hider",
	description = "Hides the fire effects on Tormented Demons to reduce eye strain",
	tags = {"tormented", "demon", "shield", "fire", "effects", "animation", "eye", "strain", "hide", "flicker"}
)
public class TdEffectsHiderPlugin extends Plugin
{
	private static final String TD_NAME = "Tormented Demon";
	private static final String CONFIG_GROUP = "tdeffectshider";

	@Inject
	private TdEffectsHiderConfig config;

	// Tracked via spawn/despawn so we never scan the whole scene each tick.
	private final Set<NPC> demons = new HashSet<>();

	// The spotanim ids to hide, rebuilt from the config toggles.
	private final Set<Integer> hideIds = new HashSet<>();

	@Override
	protected void startUp()
	{
		rebuildHideIds();
	}

	@Override
	protected void shutDown()
	{
		demons.clear();
		hideIds.clear();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CONFIG_GROUP.equals(event.getGroup()))
		{
			rebuildHideIds();
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		NPC npc = event.getNpc();
		if (isTormentedDemon(npc))
		{
			demons.add(npc);
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		demons.remove(event.getNpc());
	}

	// Hide on every client frame (~20ms) rather than once per game tick (600ms)
	// so re-applied fire spotanims are removed before they flash on screen.
	@Subscribe
	public void onClientTick(ClientTick tick)
	{
		if (demons.isEmpty() || hideIds.isEmpty())
		{
			return;
		}

		for (NPC npc : demons)
		{
			final Iterable<ActorSpotAnim> spotAnims = npc.getSpotAnims();
			if (spotAnims == null)
			{
				continue;
			}

			// Collect slot keys first, then remove, so we don't mutate the
			// table while iterating it.
			List<Integer> removeSlots = null;
			for (ActorSpotAnim spotAnim : spotAnims)
			{
				final int id = spotAnim.getId();
				if (id > 0 && hideIds.contains(id))
				{
					if (removeSlots == null)
					{
						removeSlots = new ArrayList<>();
					}
					// getHash() is the slot key used to store this spotanim.
					removeSlots.add((int) spotAnim.getHash());
				}
			}

			if (removeSlots != null)
			{
				for (int slot : removeSlots)
				{
					npc.removeSpotAnim(slot);
				}
			}
		}
	}

	// Build the hide set from the named toggles. Spotanim ids come from the
	// gameval catalogue (LUC2_UNDEAD_DEMON_* is the Tormented Demon rework).
	private void rebuildHideIds()
	{
		hideIds.clear();

		if (config.hideBodyFire())
		{
			hideIds.add(SpotanimID.LUC2_UNDEAD_DEMON_SHIELD_SPOT);
		}
		if (config.hideShieldRestore())
		{
			hideIds.add(SpotanimID.LUC2_UNDEAD_DEMON_SHIELD_RESTORE_SPOT);
		}
		if (config.hideMelee())
		{
			hideIds.add(SpotanimID.LUC2_UNDEAD_DEMON_MELEE_SPOT);
		}
		if (config.hideDeath())
		{
			hideIds.add(SpotanimID.LUC2_UNDEAD_DEMON_DEATH_SPOT);
		}
		if (config.hideExplosion())
		{
			hideIds.add(SpotanimID.LUC2_UNDEAD_DEMON_EXPLOSION_FIRE_SPOT);
			hideIds.add(SpotanimID.LUC2_UNDEAD_DEMON_FIREBALL_IMPACT_SPOT);
			hideIds.add(SpotanimID.LUC2_UNDEAD_DEMON_FIREBALL_IMPACT);
			hideIds.add(SpotanimID.LUC2_UNDEAD_DEMON_FIREBALL_LARGE_IMPACT);
		}
		if (config.hideSummon())
		{
			hideIds.add(SpotanimID.WGS_UNDEAD_DEMON_SUMMON_SPOTANIM);
		}
	}

	private static boolean isTormentedDemon(NPC npc)
	{
		final String name = npc.getName();
		return name != null && name.equalsIgnoreCase(TD_NAME);
	}

	@Provides
	TdEffectsHiderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TdEffectsHiderConfig.class);
	}
}
